private void generateSetterMethodsForBuilder(final SuperBuilderJob job, BuilderFieldData fieldNode, final String builderGenericName, String setterPrefix) {
	boolean deprecate = isFieldDeprecated(fieldNode.originalFieldNode);
	final JavacTreeMaker maker = job.getTreeMaker();
	ExpressionMaker returnTypeMaker = new ExpressionMaker() { @Override public JCExpression make() {
		return maker.Ident(job.toName(builderGenericName));
	}};

	StatementMaker returnStatementMaker = new StatementMaker() { @Override public JCStatement make() {
		return maker.Return(maker.Apply(List.<JCExpression>nil(), maker.Ident(job.toName(SELF_METHOD)), List.<JCExpression>nil()));
	}};

	if (fieldNode.singularData == null || fieldNode.singularData.getSingularizer() == null) {
		generateSimpleSetterMethodForBuilder(job, deprecate, fieldNode.createdFields.get(0), fieldNode.name, fieldNode.nameOfSetFlag, returnTypeMaker.make(), returnStatementMaker.make(), fieldNode.annotations, fieldNode.originalFieldNode, setterPrefix);
	} else {
		fieldNode.singularData.getSingularizer().generateMethods(job.checkerFramework, fieldNode.singularData, deprecate, job.builderType,
			job.sourceNode, true, returnTypeMaker, returnStatementMaker, AccessLevel.PUBLIC);
	}
}

private void generateSimpleSetterMethodForBuilder(SuperBuilderJob job, boolean deprecate, JavacNode fieldNode, Name paramName, Name nameOfSetFlag, JCExpression returnType, JCStatement returnStatement, List<JCAnnotation> annosOnParam, JavacNode originalFieldNode, String setterPrefix) {
	String setterName = HandlerUtil.buildAccessorName(job.sourceNode, setterPrefix, paramName.toString());
	Name setterName_ = job.builderType.toName(setterName);

	for (JavacNode child : job.builderType.down()) {
		if (child.getKind() == Kind.METHOD) {
			JCMethodDecl methodDecl = (JCMethodDecl) child.get();
			if (methodDecl.name.equals(setterName_)) {
				List<JCAnnotation> existingAnns = methodDecl.getModifiers().getAnnotations();
				if (existingAnns != null) {
					boolean tolerated = false;
					for (JCTree.JCAnnotation anno : existingAnns) {
						if (typeMatches(Tolerate.class, fieldNode, anno.getAnnotationType())) {
							tolerated = true;
							break;
						}
					}
					if (!tolerated) return;
				} else {
					return;
				}
			}
		}
	}

	JavacTreeMaker maker = fieldNode.getTreeMaker();
	List<JCAnnotation> methodAnns = findCopyableToSetterAnnotations(originalFieldNode);

	if (job.checkerFramework.generateReturnsReceiver()) {
		JCAnnotation rrAnnotation = maker.Annotation(genTypeRef(job.builderType, CheckerFrameworkVersion.NAME__RETURNS_RECEIVER), List.<JCExpression>nil());
		returnType = maker.AnnotatedType(List.of(rrAnnotation), returnType);
	}

	JCVariableDecl fieldDecl = (JCVariableDecl) fieldNode.get();
	JCExpression fieldRef = createFieldAccessor(maker, fieldNode, FieldAccess.ALWAYS_FIELD);
	JCAssign assign = maker.Assign(fieldRef, maker.Ident(paramName));
	ListBuffer<JCStatement> statements = new ListBuffer<JCStatement>();
	java.util.List<TypeName> configuredCopyable = fieldNode.getAst().readConfiguration(ConfigurationKeys.COPYABLE_ANNOTATIONS);
	ListBuffer<JCAnnotation> copyableBuffer = new ListBuffer<JCAnnotation>();
	for (JavacNode child : fieldNode.down()) {
		if (child.getKind() == Kind.ANNOTATION) {
			JCAnnotation annotation = (JCAnnotation) child.get();
			boolean match = false;
			for (TypeName cn : configuredCopyable) {
				if (cn != null) {
					if (typeMatches(cn.toString(), fieldNode, annotation.annotationType)) {
						copyableBuffer.append(annotation);
						match = true;
						break;
					}
				}
			}
			if (!match) {
				for (String bn : BASE_COPYABLE_ANNOTATIONS) {
					if (typeMatches(bn, fieldNode, annotation.annotationType)) {
						copyableBuffer.append(annotation);
						break;
					}
				}
			}
		}
	}
	List<JCAnnotation> copyableAnnotations = copyAnnotations(copyableBuffer.toList());
	Name methodName = fieldNode.toName(setterName);
	List<JCAnnotation> annsOnParam = copyAnnotations(annosOnParam).appendList(copyableAnnotations);
	long flags = addFinalIfNeeded(Flags.PARAMETER, fieldNode.getContext());
	JCExpression pType = cloneType(maker, fieldDecl.vartype, job.sourceNode);
	JCVariableDecl param = maker.VarDef(maker.Modifiers(flags, annsOnParam), paramName, pType, null);

	if (!hasNonNullAnnotations(fieldNode) && !hasNonNullAnnotations(fieldNode, annosOnParam)) {
		statements.append(maker.Exec(assign));
	} else {
		JCStatement nullCheck = generateNullCheck(maker, fieldDecl.vartype, paramName, job.sourceNode, null);
		if (nullCheck != null) {
			statements.append(nullCheck);
		}
		statements.append(maker.Exec(assign));
	}

	if (nameOfSetFlag != null) {
		JCAssign setBool = maker.Assign(maker.Ident(nameOfSetFlag), maker.Literal(CTC_BOOLEAN, 1));
		statements.append(maker.Exec(setBool));
	}
	statements.append(returnStatement);

	JCBlock methodBody = maker.Block(0, statements.toList());
	List<JCTypeParameter> methodGenericParams = List.nil();
	List<JCVariableDecl> parameters = List.of(param);
	List<JCExpression> throwsClauses = List.nil();
	JCExpression annotationMethodDefaultValue = null;
	List<JCAnnotation> annsOnMethod = mergeAnnotations(copyAnnotations(methodAnns), findCopyableToSetterAnnotations(fieldNode));
	boolean fieldDeprecated = false;
	if (fieldNode.get() instanceof JCVariableDecl) {
		if ((fieldDecl.mods.flags & Flags.DEPRECATED) != 0) {
			fieldDeprecated = true;
		} else {
			for (JavacNode child : fieldNode.down()) {
				if (annotationTypeMatches(Deprecated.class, child)) {
					fieldDeprecated = true;
					break;
				}
			}
		}
	}
	if (fieldDeprecated || deprecate) {
		annsOnMethod = annsOnMethod.prepend(maker.Annotation(genJavaLangTypeRef(fieldNode, "Deprecated"), List.<JCExpression>nil()));
	}

	long access = Flags.PUBLIC;
	if (shouldMakeFinal(fieldNode, getAccessorsForField(fieldNode))) {
		access |= Flags.FINAL;
	}
	JCMethodDecl methodDef = maker.MethodDef(maker.Modifiers(access, annsOnMethod), methodName, returnType,
		methodGenericParams, parameters, throwsClauses, methodBody, annotationMethodDefaultValue);
	createRelevantNonNullAnnotation(job.sourceNode, methodDef);
	JCMethodDecl newMethod = recursiveSetGeneratedBy(methodDef, job.sourceNode);

	try {
		final JCCompilationUnit cu = (JCCompilationUnit) fieldNode.top().get();
		final JCTree javadocNode = fieldNode.get();
		String javadoc = Javac.getDocComment(cu, javadocNode);
		String setterJavadoc = getJavadocSection(javadoc, "SETTER");
		final boolean sectionBased = setterJavadoc != null;
		if (!sectionBased) {
			setterJavadoc = stripLinesWithTagFromJavadoc(stripSectionsFromJavadoc(javadoc), HandlerUtil.JavadocTag.RETURN);
		}
		fieldNode.getAst().cleanupTask("javadocfilter-setter", javadocNode, new CleanupTask() {
			@Override public void cleanup() {
				String remaining = Javac.getDocComment(cu, javadocNode);
				if (remaining == null || remaining.isEmpty()) return;
				remaining = stripSectionsFromJavadoc(remaining);
				if (!sectionBased) {
					remaining = stripLinesWithTagFromJavadoc(stripSectionsFromJavadoc(remaining), HandlerUtil.JavadocTag.PARAM);
				}
				Javac.setDocComment(cu, javadocNode, remaining);
			}
		});
		if (shouldReturnThis(fieldNode, getAccessorsForField(fieldNode))) {
			setterJavadoc = addReturnsThisIfNeeded(setterJavadoc);
		}
		setterJavadoc = addReturnsThisIfNeeded(setterJavadoc);
		Javac.setDocComment(cu, newMethod, setterJavadoc);
	} catch (Exception ignore) {}

	injectMethod(job.builderType, newMethod);
}

private void addObtainVia(BuilderFieldData bfd, JavacNode node) {
	for (JavacNode child : node.down()) {
		if (!annotationTypeMatches(ObtainVia.class, child)) continue;
		AnnotationValues<ObtainVia> ann = createAnnotation(ObtainVia.class, child);
		bfd.obtainVia = ann.getInstance();
		bfd.obtainViaNode = child;
		deleteAnnotationIfNeccessary(child, ObtainVia.class);
		return;
	}
}

